//! Sequential execution of the TOML sweep manifests generated by setup.

use crate::benchmark::BenchmarkConfig;
use crate::runner;
use crate::{Error, read_config};
use serde::Deserialize;
use std::io::Write;
use std::path::{Path, PathBuf};

const MAX_SWEEP_BYTES: u64 = 64 * 1024;
const MAX_CONFIGS: usize = 256;

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct SweepFile {
    configs: Vec<String>,
}

/// Validate and execute every benchmark referenced by a sweep manifest.
pub fn run(
    path: &str,
    json: bool,
    mode: Option<crate::tape::Mode>,
    output: &mut dyn Write,
) -> Result<(), Error> {
    let sweep_path = Path::new(path);
    let text = read_sweep(sweep_path)?;
    let value: toml::Value = toml::from_str(&text)
        .map_err(|error| Error::Input(format!("cannot parse sweep {path}: {error}")))?;
    let table = value.as_table().ok_or_else(|| {
        Error::Input(format!(
            "{path} is not a sweep TOML; expected `configs = [...]`"
        ))
    })?;
    if !table.contains_key("configs") {
        return Err(Error::Input(format!(
            "{path} is not a sweep TOML; expected `configs = [...]` (a normal benchmark TOML was supplied)"
        )));
    }
    let sweep: SweepFile = value
        .try_into()
        .map_err(|error| Error::Input(format!("invalid sweep {path}: {error}")))?;
    if sweep.configs.is_empty() {
        return Err(Error::Input(format!(
            "sweep {path} contains no benchmark configurations"
        )));
    }
    if sweep.configs.len() > MAX_CONFIGS {
        return Err(Error::Input(format!(
            "sweep {path} contains {} configurations; the maximum is {MAX_CONFIGS}",
            sweep.configs.len()
        )));
    }
    let parent = sweep_path.parent().unwrap_or_else(|| Path::new("."));
    let stem = sweep_path
        .file_stem()
        .and_then(|value| value.to_str())
        .filter(|value| !value.is_empty())
        .unwrap_or("sweep");
    let results_root = parent.join(format!("{stem}-results"));
    std::fs::create_dir_all(&results_root).map_err(|error| {
        Error::Run(format!(
            "cannot create sweep results directory {}: {error}",
            results_root.display()
        ))
    })?;

    let mut failures = Vec::new();
    for (index, reference) in sweep.configs.iter().enumerate() {
        let config_path = checked_reference(parent, reference, path)?;
        let config_text = read_config(&config_path)?;
        let config_value: toml::Value = toml::from_str(&config_text).map_err(|error| {
            Error::Input(format!(
                "cannot parse benchmark {}: {error}",
                config_path.display()
            ))
        })?;
        if config_value.get("configs").is_some() {
            failures.push(format!(
                "{} is a nested sweep; sweep entries must be normal benchmark TOMLs",
                config_path.display()
            ));
            continue;
        }
        let config: BenchmarkConfig = config_value.try_into().map_err(|error| {
            Error::Input(format!(
                "invalid benchmark {}: {error}",
                config_path.display()
            ))
        })?;
        let result_dir = results_root.join(format!("{index:03}-{}", safe_name(&config_path)));
        std::fs::create_dir_all(&result_dir).map_err(|error| {
            Error::Run(format!(
                "cannot create results directory {}: {error}",
                result_dir.display()
            ))
        })?;
        let isolated = isolated_config(&config, &result_dir);
        let isolated_path = result_dir.join("benchmark.toml");
        let serialized = toml::to_string_pretty(&isolated)
            .map_err(|error| Error::Run(format!("cannot render sweep benchmark: {error}")))?;
        std::fs::write(&isolated_path, serialized).map_err(|error| {
            Error::Run(format!("cannot write {}: {error}", isolated_path.display()))
        })?;
        let cassette = None;
        if let Err(error) = runner::run_with_tape(
            isolated_path.to_string_lossy().as_ref(),
            json,
            None,
            mode,
            cassette,
            output,
        ) {
            failures.push(format!("{}: {error}", config_path.display()));
        }
    }
    if failures.is_empty() {
        Ok(())
    } else {
        Err(Error::Run(format!(
            "sweep completed with {} failed benchmark(s): {}",
            failures.len(),
            failures.join("; ")
        )))
    }
}

fn read_sweep(path: &Path) -> Result<String, Error> {
    let metadata = std::fs::metadata(path)
        .map_err(|error| Error::Input(format!("cannot read sweep {}: {error}", path.display())))?;
    if metadata.len() > MAX_SWEEP_BYTES {
        return Err(Error::Input(
            "sweep configuration is larger than 64 KiB".into(),
        ));
    }
    read_config(path)
}

fn checked_reference(parent: &Path, reference: &str, sweep: &str) -> Result<PathBuf, Error> {
    let path = Path::new(reference);
    if path.is_absolute()
        || path
            .components()
            .any(|component| component == std::path::Component::ParentDir)
    {
        return Err(Error::Input(format!(
            "sweep {sweep} contains unsafe benchmark path `{reference}`; use a relative .toml path"
        )));
    }
    if path.extension().and_then(|value| value.to_str()) != Some("toml") {
        return Err(Error::Input(format!(
            "sweep {sweep} entry `{reference}` is not a .toml benchmark"
        )));
    }
    let resolved = parent.join(path);
    if !resolved.is_file() {
        return Err(Error::Input(format!(
            "sweep {sweep} references missing benchmark {}",
            resolved.display()
        )));
    }
    Ok(resolved)
}

fn isolated_config(config: &BenchmarkConfig, result_dir: &Path) -> BenchmarkConfig {
    let mut isolated = config.clone();
    isolated.workspace = result_dir.join("workspace").to_string_lossy().into_owned();
    isolated.log_file = result_dir.join("run.log").to_string_lossy().into_owned();
    if let Some(measurements) = isolated.measurements.as_mut() {
        measurements.directory = result_dir
            .join("measurements")
            .to_string_lossy()
            .into_owned();
    }
    isolated
}

fn safe_name(path: &Path) -> String {
    path.file_stem()
        .and_then(|value| value.to_str())
        .unwrap_or("benchmark")
        .chars()
        .map(|character| {
            if character.is_ascii_alphanumeric() || matches!(character, '-' | '_' | '.') {
                character
            } else {
                '-'
            }
        })
        .collect()
}

#[cfg(test)]
mod tests {
    use super::run;
    use std::time::{SystemTime, UNIX_EPOCH};

    fn temp_file(name: &str, contents: &str) -> std::path::PathBuf {
        let stamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .expect("clock")
            .as_nanos();
        let directory = std::env::temp_dir().join(format!("asb-sweep-{stamp}"));
        std::fs::create_dir_all(&directory).expect("directory");
        let path = directory.join(name);
        std::fs::write(&path, contents).expect("file");
        path
    }

    #[test]
    fn rejects_a_normal_benchmark_as_a_sweep() {
        let path = temp_file(
            "benchmark.toml",
            "agent = \"codex\"\nworkload = \"bug-fix\"\nprovider = \"openrouter\"\nmodel = \"tool-model\"\n",
        );
        let error = run(path.to_str().expect("path"), false, None, &mut Vec::new())
            .expect_err("normal benchmark must be rejected");
        assert!(error.to_string().contains("not a sweep TOML"));
    }

    #[test]
    fn rejects_unsafe_references_before_execution() {
        let path = temp_file("sweep.toml", "configs = [\"../benchmark.toml\"]\n");
        let error = run(path.to_str().expect("path"), false, None, &mut Vec::new())
            .expect_err("parent traversal must be rejected");
        assert!(error.to_string().contains("unsafe benchmark path"));
    }
}
